style.css:
@-moz-document domain("youtube.com") {
/* ===== Fondo general ===== */
html, body, ytd-app {
    background: linear-gradient(180deg,#0b0b0f,#13131c) !important;
}

/* ===== Barra superior ===== */
#masthead-container,
tp-yt-app-header {
    background: rgba(10,10,15,.85) !important;
    backdrop-filter: blur(14px);
    border-bottom: 1px solid #3b82f6 !important;
}

/* ===== Barra lateral ===== */
#guide-content,
ytd-mini-guide-renderer {
    background: #101018 !important;
}

/* ===== Tarjetas de videos ===== */
ytd-rich-item-renderer,
ytd-video-renderer,
ytd-grid-video-renderer {
    background: #181824 !important;
    border-radius: 16px !important;
    padding: 10px !important;
    transition: .25s ease !important;
}

ytd-rich-item-renderer:hover,
ytd-video-renderer:hover,
ytd-grid-video-renderer:hover {
    transform: translateY(-5px) scale(1.02);
    box-shadow: 0 0 18px rgba(59,130,246,.55);
}

/* ===== Miniaturas ===== */
ytd-thumbnail img {
    border-radius: 14px !important;
}

/* ===== Títulos ===== */
#video-title {
    color: #ffffff !important;
    font-weight: 700 !important;
}

/* ===== Texto secundario ===== */
#metadata-line,
.ytd-video-meta-block {
    color: #bdbdbd !important;
}

/* ===== Buscador ===== */
#search-form {
    border-radius: 999px !important;
    overflow: hidden;
}

input#search {
    background: #1f1f2d !important;
    color: white !important;
}

/* ===== Botones ===== */
button,
yt-button-shape button {
    border-radius: 999px !important;
    transition: .2s ease !important;
}

button:hover,
yt-button-shape button:hover {
    background: #2563eb !important;
    color: white !important;
}

/* ===== Barra de progreso roja → azul ===== */
.ytp-play-progress {
    background: #3b82f6 !important;
}

/* ===== Barra de volumen ===== */
.ytp-volume-slider-handle,
.ytp-volume-slider-active {
    background: #3b82f6 !important;
}

/* ===== Comentarios ===== */
ytd-comment-thread-renderer {
    background: #181824 !important;
    border-radius: 12px;
    padding: 12px;
    margin: 10px 0;
}

/* ===== Scroll ===== */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #111;
}

::-webkit-scrollbar-thumb {
    background: #3b82f6;
    border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
    background: #60a5fa;
}
}
